TFM_LOW_RES = nn.Sequential(
    transforms.Resize((32, 32), antialias=True),
    transforms.Resize((64, 64), antialias=True)
    )

class ImageSuperResDataModule(ImageDataModule):
    def __init__(
        self,
        name:str = 'slegroux/tiny-imagenet-200-clean',
        data_dir:str = '../data/image',
        transform_x:Optional[transforms.Compose]=nn.Sequential(transforms.ToTensor(), TFM_LOW_RES),
        transform_y:Optional[transforms.Compose]=nn.Sequential(transforms.ToTensor()),
        train_val_split:Optional[List[float]] = [0.8, 0.2],
        batch_size:int = 64,
        num_workers:int = 0,
        pin_memory:bool = False,
        persistent_workers:bool = False,
        revision:Optional[str]=None, # pin the hub dataset to a commit sha; None tracks main
        **kwargs
    ):
        logger.info(f"Init ImageSuperResDataModule for {name}")
        self.save_hyperparameters()

        super().__init__(
            name=name,
            data_dir=data_dir,
            train_val_split=train_val_split,
            batch_size=batch_size,
            num_workers=num_workers,
            pin_memory=pin_memory,
            persistent_workers=persistent_workers,
            revision=revision,
            **kwargs
            )

        self.train_ds, self.test_ds, self.val_ds = None, None, None
        self._num_classes = None
        self.int2str = None

    def _make_ds(self, split: str) -> ImageSuperResDataset:
        return ImageSuperResDataset(
            name=self.hparams.name,
            data_dir=self.hparams.data_dir,
            transform_x=self.hparams.transform_x,
            transform_y=self.hparams.transform_y,
            revision=self.hparams.revision,
            split=split
            )

    def prepare_data(self) -> None:
        """Download/cache data only (runs on local rank 0). Do not assign state here."""
        train = self._make_ds('train')
        for split in ('test', 'validation'):
            if split in train.splits:
                self._make_ds(split)

    def setup(self, stage: Optional[str] = None) -> None:
        if self.train_ds is not None:
            return
        self.train_ds = self._make_ds('train')
        splits = self.train_ds.splits
        if 'test' in splits:
            self.test_ds = self._make_ds('test')
        if 'validation' in splits:
            self.val_ds = self._make_ds('validation')
        # no explicit test/val: reuse the other, else split train
        if self.val_ds is None and self.test_ds is not None:
            self.val_ds = self.test_ds
            logger.warning("same dataset for validation and test")
        elif self.test_ds is None and self.val_ds is not None:
            self.test_ds = self.val_ds
            logger.warning("same dataset for validation and test")
        elif self.val_ds is None:
            self._split_train_val()
            self.test_ds = self.val_ds
            logger.warning("no test/validation split: split train, val used as test")

    def show(self, idx:int):
        x, y = self.train_ds[idx]
        fig, ax = plt.subplots(1,2, figsize=(10,5))
        fig.tight_layout()
        ax[0].imshow(x.permute(1,2,0).squeeze())
        ax[0].set_title('low res')
        ax[1].imshow(y.permute(1,2,0).squeeze())
        ax[1].set_title('high res')

